[Form]
public class NDXIntrastatCheck extends FormRun
{
    NDXIntrastat   oIntrastat;
    int         filterMonth;
    int         filterYear;
    TaxCode taxCode, taxCode2;
    QueryBuildRange qbrTaxTransTransDate;
    QueryBuildRange qbrIntrastatTransDate, qbrIntrastatSumTransDate;
    QueryBuildRange qbrTaxCode, qbrTaxCode2, qbrTaxSumCode;
    QueryBuildRange qbrIntrastatDiffMonat, qbrIntrastatDiffJahr;
    QueryBuildRange qbrTaxTransSumTransDate;

    #define.CurrentVersion(2)
    #localmacro.CurrentList
        filterMonth,
        filterYear,
        taxCode, taxCode2
    #endmacro

}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void FilterDateChanged()
{
    ;
    oIntrastat.setFilterDate(filterMonth, filterYear);

    oIntrastat.setDateRange2qbr(qbrTaxTransTransDate);
    TaxTrans_DS.executeQuery();

    oIntrastat.setDateRange2qbr(qbrIntrastatTransDate);
    Intrastat_DS.executeQuery();

    oIntrastat.setDateRange2qbr(qbrIntrastatSumTransDate);
    IntrastatSum_ds.executeQuery();

    oIntrastat.setDateRange2qbr(qbrTaxTransSumTransDate);
    TaxTransSum_ds.executeQuery();

    qbrIntrastatDiffJahr.value(QueryValue(filterYear));
    qbrIntrastatDiffMonat.value(QueryValue(filterMonth));
    NDXIntrastatDiff_ds.executeQuery();
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void initParmDefault()
{
    ;
    filterMonth     = mthofyr(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    filterMonth     = filterMonth == 1 ? 12 : filterMonth - 1;
    filterYear      = year(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    taxCode         = '';

}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void close()
{
    super();

    filterMonth = ieFilterMonth.value();
    filterYear = ieFilterYear.value();       
    taxCode = seTaxCode.valueStr();
    taxCode2 = seTaxCode2.valueStr();                                           

    xSysLastValue::saveLast(this);
}

