/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "_packedClass">container</param>
/// <returns>boolean</returns>
public boolean unpack(container _packedClass)
{

    Version version = conpeek(_packedClass,1);

    switch (version)
    {
        case #CurrentVersion :
            [version,#CurrentList] = _packedClass;
            break;

        default :
            return false;
    }

    return true;
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <returns>container</returns>
public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    super();

    xSysLastValue::getLast(this);
    ieFilterMonth.value(filterMonth);
    ieFilterYear.value(filterYear);
    seTaxCode.text(taxCode);
    seTaxCode2.text(taxCode2);

    oIntrastat = new NDXIntrastat();
    oIntrastat.parmTaxCode(taxCode);
    oIntrastat.parmTaxCode2(taxCode2);
    oIntrastat.setTaxCodeQbr(qbrTaxCode);
    oIntrastat.setTaxCodeQbr(qbrTaxSumCode);

    NavigationList.visible(true);
    element.FilterDateChanged();
    element.refreshButtonGroups();

    //TODO: DebuC
    ////grdVendTrans.autoSizeColumns(false);
    //grdLedgerTrans.autoSizeColumns(false);
    ////grdVendInvoiceTrans.autoSizeColumns(false);
    //grdNDX_IntrastatDiffLine_Sum.autoSizeColumns(false);
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
private void refreshButtonGroups()
{
    if(tpTax.isActivePage())
    {
        btngrpTax.visible(true);
        btngrpIntrastat.visible(false);
        btngrpDifferences.visible(false);
    }

    if(tpIntrastatDetails.isActivePage())
    {
        btngrpTax.visible(false);
        btngrpIntrastat.visible(true);
        btngrpDifferences.visible(false);
    }

    if(tpDifferences.isActivePage())
    {
        btngrpTax.visible(false);
        btngrpIntrastat.visible(false);
        btngrpDifferences.visible(true);
    }
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    ;
    super();

    qbrTaxTransTransDate = this.query().dataSourceName(this.name()).addRange(fieldnum(TaxTrans, TransDate));
    qbrTaxCode = this.query().dataSourceName(this.name()).addRange(fieldnum(TaxTrans, TaxCode));
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    QueryBuildDataSource    qbds;
    ;
    super();
    qbds = this.query().dataSourceName(this.name());
    qbds.addRange(fieldnum(Intrastat, DebCredType)).value(QueryValue(ModuleInventCustVend::Vend));
    qbrIntrastatTransDate = qbds.addRange(fieldnum(Intrastat, TransDate));
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    QueryBuildDataSource    qbds;
    ;
    super();

    qbds = this.query().dataSourceName(this.name());
    qbrIntrastatDiffJahr = qbds.addRange(fieldnum(NDXIntrastatDiff, Jahr));
    qbrIntrastatDiffMonat = qbds.addRange(fieldnum(NDXIntrastatDiff, Monat));
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    QueryBuildDataSource    qbds;
    ;
    super();

    qbds = this.query().dataSourceName(this.name());
    qbrTaxTransSumTransDate = qbds.addRange(fieldnum(TaxTrans, TransDate));
    qbds.addGroupByField(fieldnum(TaxTrans, dataAreaId));
    qbds.addGroupByField(fieldnum(TaxTrans, Source));
    qbds.addSelectionField(fieldnum(TaxTrans, TaxBaseAmount), SelectionField::Sum);

    qbrTaxSumCode = qbds.addRange(fieldnum(TaxTrans, TaxCode));
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void init()
{
    QueryBuildDataSource    qbds;
    ;
    super();
    qbds = this.query().dataSourceName(this.name());
    qbds.addRange(fieldnum(Intrastat, DebCredType)).value(QueryValue(ModuleInventCustVend::Vend));
    qbrIntrastatSumTransDate = qbds.addRange(fieldnum(Intrastat, TransDate));

    qbds.addGroupByField(fieldnum(Intrastat, dataAreaId));
    qbds.addGroupByField(fieldnum(Intrastat, Direction));
    qbds.addSelectionField(fieldnum(Intrastat, AmountMST), SelectionField::Sum);
    qbds.addSelectionField(fieldnum(Intrastat, Weight), SelectionField::Sum);
}

