{
    super();

    this.query().dataSourceName(this.name()).addSortField(fieldnum(NDXIntrastatTransHistory, DateFrom), SortOrder::Descending);
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
public void clicked()
{
    ;
    this.enabled(false);
    super();

    oIntrastat.checkDiff();
    NDXIntrastatDiff_ds.executeQuery();
    this.enabled(true);
}

